ALTER TABLE "columns" ADD CONSTRAINT "columns_name_check" CHECK ("name" <> '' AND "name" !~ '^[ \t\n\v\f\r\u00a0\u1680\u2000-\u200a\u2028\u2029\u202f\u205f\u3000\ufeff]|[ \t\n\v\f\r\u00a0\u1680\u2000-\u200a\u2028\u2029\u202f\u205f\u3000\ufeff]$' AND char_length("name") <= 40);
